// Did the proof actually execute the code this PR changed?
// Pure mapping from (Playwright JS coverage entries, git diff text) to
// touchedChangedCode: 'yes' | 'no' | 'unknown'. This is a signal next to the
// verdict, never part of it: verdicts are decided only in verdict.js.
//
// The mapping is by content, not by file path: the browser often runs inline
// scripts generated by server code, so coverage URLs rarely name repo files.
// A 'no' means the browser never executed any line the PR added; for a
// server-only change that is expected, not damning.

const MIN_LINE = 10;

export function addedLines(diffText) {
  if (typeof diffText !== 'string' || diffText === '') return [];
  const lines = [];
  for (const raw of diffText.split('\n')) {
    if (!raw.startsWith('+') || raw.startsWith('+++')) continue;
    const line = raw.slice(1).trim();
    if (line.length >= MIN_LINE && /[A-Za-z]/.test(line)) lines.push(line);
  }
  return lines;
}

function mergeIntervals(intervals) {
  const sorted = [...intervals].sort((a, b) => a[0] - b[0]);
  const out = [];
  for (const [s, e] of sorted) {
    if (e <= s) continue;
    const last = out[out.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);
    else out.push([s, e]);
  }
  return out;
}

function subtractIntervals(covered, holes) {
  let out = covered;
  for (const [hs, he] of mergeIntervals(holes)) {
    const next = [];
    for (const [s, e] of out) {
      if (he <= s || hs >= e) {
        next.push([s, e]);
        continue;
      }
      if (hs > s) next.push([s, hs]);
      if (he < e) next.push([he, e]);
    }
    out = next;
  }
  return out;
}

// One coverage entry is { source, functions: [{ ranges: [{ startOffset,
// endOffset, count }] }] } (url ignored: inline scripts carry the page URL).
// Within an entry, count-0 ranges refine an enclosing executed range, so
// executed text = union(count > 0) minus union(count === 0), per entry.
export function executedTexts(entries) {
  const texts = [];
  for (const entry of entries ?? []) {
    const source = entry?.source;
    if (typeof source !== 'string' || source === '') continue;
    const covered = [];
    const holes = [];
    for (const fn of entry.functions ?? []) {
      for (const r of fn.ranges ?? []) {
        (r.count > 0 ? covered : holes).push([r.startOffset, r.endOffset]);
      }
    }
    for (const [s, e] of subtractIntervals(mergeIntervals(covered), holes)) {
      texts.push(source.slice(s, e));
    }
  }
  return texts;
}

export function touchedChangedCode({ texts, diff }) {
  if (!Array.isArray(texts) || texts.length === 0) return 'unknown';
  const lines = addedLines(diff);
  if (lines.length === 0) return 'unknown';
  return lines.some((line) => texts.some((t) => t.includes(line))) ? 'yes' : 'no';
}
